static TypeCacheEntry *
lookup_type_cache(Oid type_id, int flags)
{
	(void) flags;
	switch (type_id)
	{
		case INT4OID:
			return &pg_rt_int4_typentry;
		case INT8OID:
			return &pg_rt_int8_typentry;
		case NUMERICOID:
			return &pg_rt_numeric_typentry;
		case DATEOID:
			return &pg_rt_date_typentry;
		case INT4RANGEOID:
			return &pg_rt_int4range_typentry;
		case INT8RANGEOID:
			return &pg_rt_int8range_typentry;
		case NUMRANGEOID:
			return &pg_rt_numrange_typentry;
		case DATERANGEOID:
			return &pg_rt_daterange_typentry;
		default:
			elog(ERROR, "typcache stub: unexpected type oid");
	}
}

/* rangetypes.c range_get_typcache re-expressed over the stub (fn_extra memo
 * elided: the stub lookup is already O(1) and per-iteration flinfos are
 * fresh; C's memo is a pure cache with no behavioral surface). */
static TypeCacheEntry *
range_get_typcache(FunctionCallInfo fcinfo, Oid rngtypid)
{
	TypeCacheEntry *typcache = lookup_type_cache(rngtypid, TYPECACHE_RANGE_INFO);

	if (typcache->rngelemtype == NULL)
		elog(ERROR, "type %u is not a range type", rngtypid);
	return typcache;
}

/* lsyscache get_type_io_data over the pinned instantiations */
static void
get_type_io_data(Oid typid, IOFuncSelector which_func,
				 int16 *typlen, bool *typbyval, char *typalign,
				 char *typdelim, Oid *typioparam, Oid *func)
{
	TypeCacheEntry *e = lookup_type_cache(typid, 0);

	*typlen = e->typlen;
	*typbyval = e->typbyval;
	*typalign = e->typalign;
	*typdelim = ',';
	*typioparam = typid;
	switch (typid)
	{
		case INT4OID:
			*func = (which_func == IOFunc_input) ? F_INT4IN :
				(which_func == IOFunc_output) ? F_INT4OUT :
				(which_func == IOFunc_receive) ? F_INT4RECV : F_INT4SEND;
			break;
		case INT8OID:
			*func = (which_func == IOFunc_input) ? F_INT8IN :
				(which_func == IOFunc_output) ? F_INT8OUT :
				(which_func == IOFunc_receive) ? F_INT8RECV : F_INT8SEND;
			break;
		case NUMERICOID:
			*func = (which_func == IOFunc_input) ? F_NUMERIC_IN :
				(which_func == IOFunc_output) ? F_NUMERIC_OUT :
				(which_func == IOFunc_receive) ? F_NUMERIC_RECV : F_NUMERIC_SEND;
			break;
		default:
			elog(ERROR, "get_type_io_data stub: unexpected type oid");
	}
}

static void
fmgr_info_cxt(Oid functionId, FmgrInfo *finfo, int mcxt)
{
	(void) mcxt;
	memset(finfo, 0, sizeof(*finfo));
	finfo->fn_oid = functionId;
	finfo->fn_strict = true;
	switch (functionId)
	{
		case F_INT4IN: finfo->fn_addr = int4in; break;
		case F_INT4OUT: finfo->fn_addr = int4out; break;
		case F_INT4RECV: finfo->fn_addr = int4recv; break;
		case F_INT4SEND: finfo->fn_addr = int4send; break;
		case F_INT8IN: finfo->fn_addr = int8in; break;
		case F_INT8OUT: finfo->fn_addr = int8out; break;
		case F_INT8RECV: finfo->fn_addr = int8recv; break;
		case F_INT8SEND: finfo->fn_addr = int8send; break;
		case F_NUMERIC_IN: finfo->fn_addr = numeric_in; break;
		case F_NUMERIC_OUT: finfo->fn_addr = numeric_out; break;
		case F_NUMERIC_RECV: finfo->fn_addr = numeric_recv; break;
		case F_NUMERIC_SEND: finfo->fn_addr = numeric_send; break;
		default:
			elog(ERROR, "fmgr_info stub: unexpected function oid");
	}
}

/* date.c date_cmp, verbatim */
static Datum
date_cmp(PG_FUNCTION_ARGS)
{
	DateADT		dateVal1 = PG_GETARG_DATEADT(0);
	DateADT		dateVal2 = PG_GETARG_DATEADT(1);

	if (dateVal1 < dateVal2)
		PG_RETURN_INT32(-1);
	else if (dateVal1 > dateVal2)
		PG_RETURN_INT32(1);
	PG_RETURN_INT32(0);
}


/* ==== src/common/hashfn.c macros — VERBATIM ==== */
#define rot(x,k) pg_rotate_left32(x, k)

/*----------
 * mix -- mix 3 32-bit values reversibly.
 *
 * This is reversible, so any information in (a,b,c) before mix() is
 * still in (a,b,c) after mix().
 *
 * If four pairs of (a,b,c) inputs are run through mix(), or through
 * mix() in reverse, there are at least 32 bits of the output that
 * are sometimes the same for one pair and different for another pair.
 * This was tested for:
 * * pairs that differed by one bit, by two bits, in any combination
 *	 of top bits of (a,b,c), or in any combination of bottom bits of
 *	 (a,b,c).
 * * "differ" is defined as +, -, ^, or ~^.  For + and -, I transformed
 *	 the output delta to a Gray code (a^(a>>1)) so a string of 1's (as
 *	 is commonly produced by subtraction) look like a single 1-bit
 *	 difference.
 * * the base values were pseudorandom, all zero but one bit set, or
 *	 all zero plus a counter that starts at zero.
 *
 * This does not achieve avalanche.  There are input bits of (a,b,c)
 * that fail to affect some output bits of (a,b,c), especially of a.  The
 * most thoroughly mixed value is c, but it doesn't really even achieve
 * avalanche in c.
 *
 * This allows some parallelism.  Read-after-writes are good at doubling
 * the number of bits affected, so the goal of mixing pulls in the opposite
 * direction from the goal of parallelism.  I did what I could.  Rotates
 * seem to cost as much as shifts on every machine I could lay my hands on,
 * and rotates are much kinder to the top and bottom bits, so I used rotates.
 *----------
 */
#define mix(a,b,c) \
{ \
  a -= c;  a ^= rot(c, 4);	c += b; \
  b -= a;  b ^= rot(a, 6);	a += c; \
  c -= b;  c ^= rot(b, 8);	b += a; \
  a -= c;  a ^= rot(c,16);	c += b; \
  b -= a;  b ^= rot(a,19);	a += c; \
  c -= b;  c ^= rot(b, 4);	b += a; \
}

/*----------
 * final -- final mixing of 3 32-bit values (a,b,c) into c
 *
 * Pairs of (a,b,c) values differing in only a few bits will usually
 * produce values of c that look totally different.  This was tested for
 * * pairs that differed by one bit, by two bits, in any combination
 *	 of top bits of (a,b,c), or in any combination of bottom bits of
 *	 (a,b,c).
 * * "differ" is defined as +, -, ^, or ~^.  For + and -, I transformed
 *	 the output delta to a Gray code (a^(a>>1)) so a string of 1's (as
 *	 is commonly produced by subtraction) look like a single 1-bit
 *	 difference.
 * * the base values were pseudorandom, all zero but one bit set, or
 *	 all zero plus a counter that starts at zero.
 *
 * The use of separate functions for mix() and final() allow for a
 * substantial performance increase since final() does not need to
 * do well in reverse, but is does need to affect all output bits.
 * mix(), on the other hand, does not need to affect all output
 * bits (affecting 32 bits is enough).  The original hash function had
 * a single mixing operation that had to satisfy both sets of requirements
 * and was slower as a result.
 *----------
 */
#define final(a,b,c) \
{ \
  c ^= b; c -= rot(b,14); \
  a ^= c; a -= rot(c,11); \
  b ^= a; b -= rot(a,25); \
  c ^= b; c -= rot(b,16); \
  a ^= c; a -= rot(c, 4); \
  b ^= a; b -= rot(a,14); \
  c ^= b; c -= rot(b,24); \
}

