/* ========== fuzz-facing driver entries (NOT Postgres code) ========== */

/*
 * Every entry: arena reset, errcode = 0, setjmp recovery point (hard
 * ereport/elog longjmps land here and surface as the recorded class).
 * Returns 0 = ok, >0 = errcode class. Results ride caller buffers;
 * -1 = caller buffer too small (harness bug, never a divergence).
 */
#define PG_DIFF_ENTER() \
	do { \
		pg_diff_arena_reset(); \
		pg_diff_errcode = 0; \
		if (setjmp(pg_diff_rt_jmp)) \
			return pg_diff_errcode ? pg_diff_errcode : 99; \
	} while (0)

/*
 * PER-CALL GUARD. The bundled entries below drive SEVERAL fmgr calls per
 * invocation for cheap coverage, but each call must carry its OWN errcode:
 * one shared code conflated "which operator errored" and made
 * range_adjacent's legitimate 22003 (int4range_canonical at INT32_MAX) abort
 * the whole bundle, which the driver then compared against range_eq's
 * perfectly good result — a false divergence (harness defect, 2026-07-31).
 * The shipped Rust calls every wrapper independently, so the oracle must too.
 */
#define PG_DIFF_CALL(errslot, stmt) \
	do { \
		pg_diff_arena_reset(); \
		pg_diff_errcode = 0; \
		if (setjmp(pg_diff_rt_jmp)) \
			(errslot) = pg_diff_errcode ? pg_diff_errcode : 99; \
		else \
		{ \
			stmt; \
			(errslot) = 0; \
		} \
	} while (0)

static Oid
pg_rt_typ_oid(int typ)
{
	switch (typ)
	{
		case 0:
			return INT4RANGEOID;
		case 1:
			return INT8RANGEOID;
		case 2:
			return NUMRANGEOID;
		default:
			return DATERANGEOID;
	}
}

/*
 * SOFT-ERROR (escontext) CARRIER.
 *
 * C range_in reads its soft-error context straight off the frame
 * (`Node *escontext = fcinfo->context`), and this file's `ereturn` shim already
 * returns the caller's dummy value instead of longjmp'ing whenever escontext is
 * non-NULL, while SOFT_ERROR_OCCURRED reads the recorded class. `Node` is
 * opaque here (typedef at the top: "only ever NULL / err-flag carrier"), so
 * soft mode is exactly the hard-mode entry with ANY non-NULL address threaded
 * into fcinfo->context. This static is that address.
 */
static char pg_diff_soft_marker;
#define PG_DIFF_SOFT_ESC ((Node *) (void *) &pg_diff_soft_marker)

/* one fmgr call on a fresh flinfo (fn_extra NULL, fn_rettype armed) */
static Datum
pg_rt_call_ctx(PGFunction fn, Oid rettype, int nargs,
			   const Datum *args, const bool *nulls, bool *isnull_out,
			   Node *escontext);

static Datum
pg_rt_call(PGFunction fn, Oid rettype, int nargs,
		   const Datum *args, const bool *nulls, bool *isnull_out)
{
	return pg_rt_call_ctx(fn, rettype, nargs, args, nulls, isnull_out, NULL);
}

static Datum
pg_rt_call_ctx(PGFunction fn, Oid rettype, int nargs,
			   const Datum *args, const bool *nulls, bool *isnull_out,
			   Node *escontext)
{
	FmgrInfo	flinfo;
	LOCAL_FCINFO(fcinfo, 3);
	Datum		d;
	int			i;

	memset(&flinfo, 0, sizeof(flinfo));
	flinfo.fn_addr = fn;
	flinfo.fn_rettype = rettype;
	InitFunctionCallInfoData(*fcinfo, &flinfo, nargs, InvalidOid, escontext, NULL);
	for (i = 0; i < nargs; i++)
	{
		fcinfo->args[i].value = args[i];
		fcinfo->args[i].isnull = nulls ? nulls[i] : false;
	}
	d = FunctionCallInvoke(fcinfo);
	if (isnull_out)
		*isnull_out = fcinfo->isnull;
	return d;
}

/*
 * SQL-NULL is a COMPARED plane, not an ignored one: every entry that copies a
 * by-ref result reports isnull as class PG_DIFF_ISNULL so the driver can hold
 * it against the Rust wrapper's own isnull flag. Dereferencing an unreported
 * SQL NULL was the pg_diff_range_accessors SEGV shape (lane p1-laneac).
 */
#define PG_DIFF_ISNULL 97

static int
pg_rt_copy_range(Datum d, bool isnull, unsigned char *out, int *outlen, int outcap)
{
	RangeType  *r;
	int			n;

	if (isnull)
		return PG_DIFF_ISNULL;
	r = DatumGetRangeTypeP(d);
	if (r == NULL)
		return PG_DIFF_ISNULL;
	n = (int) VARSIZE(r);
	if (n > outcap)
		return -1;
	memcpy(out, r, n);
	*outlen = n;
	return 0;
}

int
pg_diff_range_in(int typ, const char *str,
				 unsigned char *out, int *outlen, int outcap)
{
	Datum		args[3];
	Datum		d;
	bool		isnull;

	PG_DIFF_ENTER();
	args[0] = CStringGetDatum(str);
	args[1] = ObjectIdGetDatum(pg_rt_typ_oid(typ));
	args[2] = Int32GetDatum(-1);
	d = pg_rt_call(range_in, InvalidOid, 3, args, NULL, &isnull);
	return pg_rt_copy_range(d, isnull, out, outlen, outcap);
}

/*
 * range_in in SOFT-ERROR mode: the same call with an escontext threaded, which
 * is the surface behind pg_input_is_valid() and COPY ... ON_ERROR ignore.
 *
 * Reports the soft outcome through out-parameters rather than the return value,
 * because in soft mode an invalid input is NOT an error from the caller's point
 * of view: C returns normally and the caller inspects the context.
 *   *soft_class = the recorded errcode class (0 = no soft error)
 *   *isnull_out = fcinfo->isnull as C left it (a COMPARED sub-plane: C reaches
 *                 PG_RETURN_NULL on the parse / element-input soft edges but
 *                 returns a NULL RangeType pointer with isnull=false on the
 *                 make_range edge, and those are different fmgr contracts)
 * Return value is the image length class exactly as the hard entry: 0 = a range
 * image was produced, PG_DIFF_ISNULL = SQL NULL, -1 = out of buffer.
 */
int
pg_diff_range_in_soft(int typ, const char *str,
					  unsigned char *out, int *outlen, int outcap,
					  int *soft_class, int *isnull_out)
{
	Datum		args[3];
	Datum		d;
	bool		isnull;
	int			rc;

	*soft_class = 0;
	*isnull_out = 0;
	PG_DIFF_ENTER();
	args[0] = CStringGetDatum(str);
	args[1] = ObjectIdGetDatum(pg_rt_typ_oid(typ));
	args[2] = Int32GetDatum(-1);
	d = pg_rt_call_ctx(range_in, InvalidOid, 3, args, NULL, &isnull,
					   PG_DIFF_SOFT_ESC);
	*soft_class = pg_diff_errcode;
	*isnull_out = isnull ? 1 : 0;
	if (*soft_class != 0)
		return 0;				/* soft failure: no image to compare */
	rc = pg_rt_copy_range(d, isnull, out, outlen, outcap);
	return rc;
}

int
pg_diff_range_out(const unsigned char *img, char *out, int *outlen, int outcap)
{
	Datum		args[1];
	Datum		d;
	bool		isnull;
	int			n;

	PG_DIFF_ENTER();
	args[0] = PointerGetDatum(img);
	d = pg_rt_call(range_out, InvalidOid, 1, args, NULL, &isnull);
	if (isnull || DatumGetCString(d) == NULL)
		return PG_DIFF_ISNULL;
	n = (int) strlen(DatumGetCString(d));
	if (n + 1 > outcap)
		return -1;
	memcpy(out, DatumGetCString(d), n + 1);
	*outlen = n;
	return 0;
}

int
pg_diff_range_recv(int typ, const unsigned char *wire, int wirelen,
				   unsigned char *out, int *outlen, int outcap)
{
	StringInfoData buf;
	Datum		args[3];
	Datum		d;
	bool		isnull;

	PG_DIFF_ENTER();
	initStringInfo(&buf);
	appendBinaryStringInfo(&buf, wire, wirelen);
	buf.cursor = 0;
	args[0] = PointerGetDatum(&buf);
	args[1] = ObjectIdGetDatum(pg_rt_typ_oid(typ));
	args[2] = Int32GetDatum(-1);
	d = pg_rt_call(range_recv, InvalidOid, 3, args, NULL, &isnull);
	return pg_rt_copy_range(d, isnull, out, outlen, outcap);
}

int
pg_diff_range_send(const unsigned char *img,
				   unsigned char *out, int *outlen, int outcap)
{
	Datum		args[1];
	Datum		d;
	bool		isnull;
	bytea	   *b;
	int			n;

	PG_DIFF_ENTER();
	args[0] = PointerGetDatum(img);
	d = pg_rt_call(range_send, InvalidOid, 1, args, NULL, &isnull);
	if (isnull)
		return PG_DIFF_ISNULL;
	b = DatumGetByteaP(d);
	n = (int) (VARSIZE(b) - VARHDRSZ);
	if (n > outcap)
		return -1;
	memcpy(out, VARDATA(b), n);
	*outlen = n;
	return 0;
}

/* bound payload -> Datum per instantiation (typ 2 = numeric varlena ptr) */
static Datum
pg_rt_bound_datum(int typ, int64 v, const unsigned char *numptr)
{
	switch (typ)
	{
		case 0:
			return Int32GetDatum((int32) v);
		case 1:
			return Int64GetDatum(v);
		default:
			/* byref element: a NULL bound pointer is a DRIVER bug, and the
			 * verbatim bodies would dereference it — abort loudly instead of
			 * segfaulting inside a C body. */
			assert(numptr != NULL);
			return PointerGetDatum(numptr);
	}
}

int
pg_diff_range_ctor(int typ, int nargs,
				   int64 v1, int64 v2,
				   const unsigned char *n1, const unsigned char *n2,
				   int null1, int null2,
				   const unsigned char *flags_txt, int flags_len,
				   int null3, int soft, int *soft_class,
				   unsigned char *out, int *outlen, int outcap)
{
	Datum		args[3];
	bool		nulls[3] = {null1 != 0, null2 != 0, null3 != 0};
	Datum		d;
	bool		isnull;
	Node	   *esc = soft ? PG_DIFF_SOFT_ESC : NULL;

	if (soft_class)
		*soft_class = 0;
	PG_DIFF_ENTER();
	args[0] = null1 ? (Datum) 0 : pg_rt_bound_datum(typ, v1, n1);
	args[1] = null2 ? (Datum) 0 : pg_rt_bound_datum(typ, v2, n2);
	if (nargs == 3)
	{
		/* range_constructor3 is NON-STRICT in pg_proc, so a NULL flags
		 * argument really does reach the body (C raises 22000 there); the
		 * flags text length is driven too, so range_parse_flags' length
		 * check is a compared arm and not just its character arms. */
		text	   *t = palloc(VARHDRSZ + flags_len);

		SET_VARSIZE(t, VARHDRSZ + flags_len);
		memcpy(VARDATA(t), flags_txt, flags_len);
		args[2] = null3 ? (Datum) 0 : PointerGetDatum(t);
		d = pg_rt_call_ctx(range_constructor3, pg_rt_typ_oid(typ), 3, args, nulls,
						   &isnull, esc);
	}
	else
		d = pg_rt_call_ctx(range_constructor2, pg_rt_typ_oid(typ), 2, args, nulls,
						   &isnull, esc);
	if (soft && pg_diff_errcode != 0)
	{
		/* soft failure: canonicalize overflowed and the error was captured
		 * instead of thrown, which is the make_range -> canonicalize soft edge
		 * (the daterange arm of that dispatch is otherwise unreachable). */
		if (soft_class)
			*soft_class = pg_diff_errcode;
		return 0;
	}
	return pg_rt_copy_range(d, isnull, out, outlen, outcap);
}

/*
 * Accessor bundle: lower/upper datum bytes (4/8-byte LE value for byval
 * instantiations, whole varlena image for numeric) + null flags + the five
 * boolean accessors, in one shot.
 */
int
pg_diff_range_accessors(const unsigned char *img,
						unsigned char *lower_out, int *lower_len, int *lower_null,
						unsigned char *upper_out, int *upper_len, int *upper_null,
						unsigned char *bools /* [5] */,
						int32 *errs /* [7]: lower, upper, then the 5 bools */,
						int outcap)
{
	Datum		args[1];
	Datum		d;
	bool		isnull;
	RangeType  *r;
	TypeCacheEntry *tc;
	int			i;
	struct
	{
		PGFunction	fn;
		unsigned char *out;
		int		   *len;
		int		   *nul;
	}			acc[2];

	PG_DIFF_ENTER();
	/* The HARNESS's own header read must detoast first: the driver also feeds
	 * SHORT-header (1-byte) range images, which is the form a small stored
	 * range really carries, and reading ->rangetypid off a short image lands 3
	 * bytes off and produced a bogus typcache miss. The fmgr calls below still
	 * receive the ORIGINAL datum, so each callee runs its own detoast — which
	 * is exactly the path under test. */
	r = (RangeType *) pg_rt_detoast((void *) img);
	/* SWEEP (lane p1-laneac): range_get_typcache is the C-faithful accessor and
	 * elogs when rngelemtype is unset, so the ->rngelemtype deref below cannot
	 * be reached with a non-range entry. A raw lookup_type_cache + unchecked
	 * deref was the shape audited out of this oracle. */
	tc = range_get_typcache(NULL, RangeTypeGetOid(r));
	args[0] = PointerGetDatum(img);
	acc[0].fn = range_lower;
	acc[0].out = lower_out;
	acc[0].len = lower_len;
	acc[0].nul = lower_null;
	acc[1].fn = range_upper;
	acc[1].out = upper_out;
	acc[1].len = upper_len;
	acc[1].nul = upper_null;
	for (i = 0; i < 2; i++)
	{
		isnull = false;
		PG_DIFF_CALL(errs[i],
					 d = pg_rt_call(acc[i].fn, InvalidOid, 1, args, NULL, &isnull));
		if (errs[i])
		{
			*acc[i].nul = 0;
			*acc[i].len = 0;
			continue;
		}
		*acc[i].nul = isnull;
		*acc[i].len = 0;
		if (!isnull)
		{
			if (tc->rngelemtype->typbyval)
			{
				int64		v = (int64) d;

				if (8 > outcap)
					return -1;
				memcpy(acc[i].out, &v, 8);
				*acc[i].len = 8;
			}
			else
			{
				int			n;

				/* fenced by the driver (see fence_flags): a byref bound datum
				 * reported not-null can never be NULL here. Loud, not skipped. */
				assert(DatumGetPointer(d) != NULL);
				n = (int) VARSIZE_ANY(DatumGetPointer(d));

				if (n > outcap)
					return -1;
				memcpy(acc[i].out, DatumGetPointer(d), n);
				*acc[i].len = n;
			}
		}
	}
	{
		static PGFunction bfns[5];
		int			k;

		bfns[0] = range_empty;
		bfns[1] = range_lower_inc;
		bfns[2] = range_upper_inc;
		bfns[3] = range_lower_inf;
		bfns[4] = range_upper_inf;
		for (k = 0; k < 5; k++)
		{
			Datum		bd = (Datum) 0;

			PG_DIFF_CALL(errs[2 + k],
						 bd = pg_rt_call(bfns[k], InvalidOid, 1, args, NULL, NULL));
			bools[k] = errs[2 + k] ? 0 : (unsigned char) DatumGetBool(bd);
		}
	}
	return 0;
}

/*
 * Operator bundle over one image pair:
 * res[0..14] = eq ne lt le gt ge cmp overlaps contains contained_by
 *              before after adjacent overleft overright
 */
int
pg_diff_range_ops(const unsigned char *img1, const unsigned char *img2,
				  int32 *res, int32 *errs)
{
	Datum		args[2];
	int			i;
	static PGFunction fns[15];
	static const int isbool[15] = {1, 1, 1, 1, 1, 1, 0, 1, 1, 1, 1, 1, 1, 1, 1};

	fns[0] = range_eq;
	fns[1] = range_ne;
	fns[2] = range_lt;
	fns[3] = range_le;
	fns[4] = range_gt;
	fns[5] = range_ge;
	fns[6] = range_cmp;
	fns[7] = range_overlaps;
	fns[8] = range_contains;
	fns[9] = range_contained_by;
	fns[10] = range_before;
	fns[11] = range_after;
	fns[12] = range_adjacent;
	fns[13] = range_overleft;
	fns[14] = range_overright;

	pg_diff_arena_reset();
	pg_diff_errcode = 0;
	args[0] = PointerGetDatum(img1);
	args[1] = PointerGetDatum(img2);
	for (i = 0; i < 15; i++)
	{
		Datum		d = (Datum) 0;

		PG_DIFF_CALL(errs[i], d = pg_rt_call(fns[i], InvalidOid, 2, args, NULL, NULL));
		res[i] = errs[i] ? 0 : (isbool[i] ? (int32) DatumGetBool(d) : DatumGetInt32(d));
	}
	return 0;
}

int
pg_diff_range_contains_elem(const unsigned char *img,
							int64 v, const unsigned char *numptr,
							int32 *contains, int32 *contained,
							int32 *err_contains, int32 *err_contained)
{
	RangeType  *r = (RangeType *) img;
	int			typ;
	Datum		args[2];
	Datum		swapped[2];
	Datum		d = (Datum) 0;

	pg_diff_arena_reset();
	pg_diff_errcode = 0;
	typ = (RangeTypeGetOid(r) == INT4RANGEOID) ? 0 :
		(RangeTypeGetOid(r) == INT8RANGEOID) ? 1 : 2;
	args[0] = PointerGetDatum(img);
	args[1] = pg_rt_bound_datum(typ, v, numptr);
	PG_DIFF_CALL(*err_contains,
				 d = pg_rt_call(range_contains_elem, InvalidOid, 2, args, NULL, NULL));
	*contains = *err_contains ? 0 : (int32) DatumGetBool(d);
	swapped[0] = args[1];
	swapped[1] = args[0];
	PG_DIFF_CALL(*err_contained,
				 d = pg_rt_call(elem_contained_by_range, InvalidOid, 2, swapped, NULL, NULL));
	*contained = *err_contained ? 0 : (int32) DatumGetBool(d);
	return 0;
}

/* which: 0 union, 1 intersect, 2 minus, 3 merge */
int
pg_diff_range_setop(int which, const unsigned char *img1,
					const unsigned char *img2,
					unsigned char *out, int *outlen, int outcap)
{
	Datum		args[2];
	Datum		d;
	bool		isnull;
	PGFunction	fn;

	PG_DIFF_ENTER();
	args[0] = PointerGetDatum(img1);
	args[1] = PointerGetDatum(img2);
	fn = (which == 0) ? range_union :
		(which == 1) ? range_intersect :
		(which == 2) ? range_minus : range_merge;
	d = pg_rt_call(fn, InvalidOid, 2, args, NULL, &isnull);
	return pg_rt_copy_range(d, isnull, out, outlen, outcap);
}

int
pg_diff_hash_range(const unsigned char *img, uint32 *h)
{
	Datum		args[1];

	PG_DIFF_ENTER();
	args[0] = PointerGetDatum(img);
	*h = DatumGetUInt32(pg_rt_call(hash_range, InvalidOid, 1, args, NULL, NULL));
	return 0;
}

int
pg_diff_hash_range_extended(const unsigned char *img, uint64 seed, uint64 *h)
{
	Datum		args[2];

	PG_DIFF_ENTER();
	args[0] = PointerGetDatum(img);
	args[1] = UInt64GetDatum(seed);
	*h = DatumGetUInt64(pg_rt_call(hash_range_extended, InvalidOid, 2, args, NULL, NULL));
	return 0;
}

/* typ: 0 int4range, 1 int8range, 3 daterange */
int
pg_diff_range_canonical(int typ, const unsigned char *img,
						unsigned char *out, int *outlen, int outcap)
{
	Datum		args[1];
	Datum		d;
	bool		isnull;
	PGFunction	fn;

	PG_DIFF_ENTER();
	args[0] = PointerGetDatum(img);
	fn = (typ == 0) ? int4range_canonical :
		(typ == 1) ? int8range_canonical : daterange_canonical;
	d = pg_rt_call(fn, InvalidOid, 1, args, NULL, &isnull);
	return pg_rt_copy_range(d, isnull, out, outlen, outcap);
}

/*
 * The canonical functions in SOFT-ERROR mode. This is a REAL caller shape, not
 * a harness invention: make_range invokes rng_canonical_finfo through a
 * hand-built frame precisely so it can pass escontext ("Do this the hard way so
 * that we can pass escontext" — rangetypes.c), so the canonical body genuinely
 * runs with a soft context whenever a soft range_in canonicalizes. Contract as
 * pg_diff_range_in_soft.
 */
/*
 * INTERNAL-API arm: make_range itself, hard or soft (typ as pg_rt_typ_oid:
 * 0=int4range 1=int8range 3=daterange; byval bounds only). This is the ONLY
 * route to canonicalize's per-type dispatch under a soft context — the fmgr
 * constructors hardcode a NULL escontext (range_constructor2/3 pass NULL to
 * make_range in verbatim C and in the shipped Rust alike), and range_in cannot
 * carry daterange here because date_in is not vendored. make_range is the
 * exact function real range_in calls, so this models a REAL caller shape (the
 * mr oracle's internal-API section is the precedent).
 *
 * flags: RANGE_*_INF/INC of the bounds + RANGE_EMPTY; soft-mode contract as
 * pg_diff_range_in_soft.
 */
int
pg_diff_make_range(int typ, int64 v1, int64 v2, int flags, int soft,
				   unsigned char *out, int *outlen, int outcap,
				   int *soft_class)
{
	TypeCacheEntry *tc;
	RangeBound	lower;
	RangeBound	upper;
	RangeType  *r;
	int			n;

	*soft_class = 0;
	PG_DIFF_ENTER();
	tc = range_get_typcache(NULL, pg_rt_typ_oid(typ));
	lower.val = pg_rt_bound_datum(typ == 3 ? 0 : typ, v1, NULL);
	lower.infinite = (flags & RANGE_LB_INF) != 0;
	lower.inclusive = (flags & RANGE_LB_INC) != 0;
	lower.lower = true;
	upper.val = pg_rt_bound_datum(typ == 3 ? 0 : typ, v2, NULL);
	upper.infinite = (flags & RANGE_UB_INF) != 0;
	upper.inclusive = (flags & RANGE_UB_INC) != 0;
	upper.lower = false;
	r = make_range(tc, &lower, &upper, (flags & RANGE_EMPTY) != 0,
				   soft ? PG_DIFF_SOFT_ESC : NULL);
	*soft_class = pg_diff_errcode;
	if (*soft_class != 0)
		return 0;				/* soft failure captured */
	n = (int) VARSIZE(r);
	if (n > outcap)
		return -1;
	memcpy(out, r, n);
	*outlen = n;
	return 0;
}

int
pg_diff_range_canonical_soft(int typ, const unsigned char *img,
							 unsigned char *out, int *outlen, int outcap,
							 int *soft_class, int *isnull_out)
{
	Datum		args[1];
	Datum		d;
	bool		isnull;
	PGFunction	fn;

	*soft_class = 0;
	*isnull_out = 0;
	PG_DIFF_ENTER();
	args[0] = PointerGetDatum(img);
	fn = (typ == 0) ? int4range_canonical :
		(typ == 1) ? int8range_canonical : daterange_canonical;
	d = pg_rt_call_ctx(fn, InvalidOid, 1, args, NULL, &isnull, PG_DIFF_SOFT_ESC);
	*soft_class = pg_diff_errcode;
	*isnull_out = isnull ? 1 : 0;
	if (*soft_class != 0)
		return 0;
	return pg_rt_copy_range(d, isnull, out, outlen, outcap);
}

/* which: 0 int4, 1 int8, 2 num, 3 date, 4 ts, 5 tstz */
int
pg_diff_range_subdiff(int which, int64 a, int64 b,
					  const unsigned char *na, const unsigned char *nb,
					  double *out)
{
	Datum		args[2];
	PGFunction	fn;

	PG_DIFF_ENTER();
	switch (which)
	{
		case 0:
			fn = int4range_subdiff;
			args[0] = Int32GetDatum((int32) a);
			args[1] = Int32GetDatum((int32) b);
			break;
		case 1:
			fn = int8range_subdiff;
			args[0] = Int64GetDatum(a);
			args[1] = Int64GetDatum(b);
			break;
		case 2:
			fn = numrange_subdiff;
			args[0] = PointerGetDatum(na);
			args[1] = PointerGetDatum(nb);
			break;
		case 3:
			fn = daterange_subdiff;
			args[0] = Int32GetDatum((int32) a);
			args[1] = Int32GetDatum((int32) b);
			break;
		case 4:
			fn = tsrange_subdiff;
			args[0] = Int64GetDatum(a);
			args[1] = Int64GetDatum(b);
			break;
		default:
			fn = tstzrange_subdiff;
			args[0] = Int64GetDatum(a);
			args[1] = Int64GetDatum(b);
			break;
	}
	*out = DatumGetFloat8(pg_rt_call(fn, InvalidOid, 2, args, NULL, NULL));
	return 0;
}

